ALTER TABLE users ADD COLUMN can_download INTEGER NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN can_view_adult INTEGER NOT NULL DEFAULT 0;
ALTER TABLE books ADD COLUMN description TEXT NOT NULL DEFAULT '';
ALTER TABLE books ADD COLUMN cover_key TEXT;
ALTER TABLE books ADD COLUMN group_name TEXT NOT NULL DEFAULT '默认分组';
ALTER TABLE books ADD COLUMN chapter_count INTEGER NOT NULL DEFAULT 0;
ALTER TABLE books ADD COLUMN index_key TEXT;
CREATE TABLE library_groups (kind TEXT NOT NULL CHECK(kind IN ('comic','novel')),name TEXT NOT NULL,created_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(kind,name));
INSERT INTO library_groups VALUES ('comic','默认分组',0),('novel','默认分组',0);
CREATE TABLE group_permissions (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,group_name TEXT NOT NULL,PRIMARY KEY(user_id,group_name));
CREATE TABLE comics (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,provider TEXT NOT NULL,source_url TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',cover_key TEXT,group_name TEXT NOT NULL DEFAULT '默认分组',adult INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE chapters (id TEXT PRIMARY KEY,comic_id TEXT NOT NULL REFERENCES comics(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,title TEXT NOT NULL,source_id TEXT NOT NULL,manifest_key TEXT,object_key TEXT,format TEXT NOT NULL DEFAULT 'images',page_count INTEGER NOT NULL DEFAULT 0,size INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'pending',UNIQUE(comic_id,source_id));
CREATE INDEX chapters_library ON chapters(comic_id,state,ordinal);
CREATE TABLE comic_jobs (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),comic_id TEXT REFERENCES comics(id),parent_id TEXT,kind TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,message TEXT NOT NULL DEFAULT '',reserved_bytes INTEGER NOT NULL DEFAULT 0,size INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX comic_jobs_outbox ON comic_jobs(state,updated_at);
CREATE UNIQUE INDEX comic_jobs_active_url ON comic_jobs(json_extract(payload,'$.url')) WHERE kind='source' AND state IN ('queued','running','waiting');
CREATE TABLE comic_progress (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,comic_id TEXT NOT NULL REFERENCES comics(id) ON DELETE CASCADE,chapter INTEGER NOT NULL DEFAULT 0,page INTEGER NOT NULL DEFAULT 0,scroll INTEGER NOT NULL DEFAULT 0,client_ms INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(user_id,comic_id));
CREATE TABLE reading_reports (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,media_id TEXT NOT NULL,session_id TEXT NOT NULL,seconds INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,media_id,session_id));
CREATE TABLE reading_time (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,media_id TEXT NOT NULL,day TEXT NOT NULL,seconds INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,media_id,day));
CREATE TABLE hidden_items (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,target TEXT NOT NULL,PRIMARY KEY(user_id,kind,target));
CREATE TABLE settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE login_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT NOT NULL,ip_address TEXT NOT NULL,user_agent TEXT NOT NULL,success INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE anilist_accounts (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,token TEXT NOT NULL,name TEXT NOT NULL DEFAULT '',anilist_id INTEGER);
CREATE TABLE anilist_links (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,comic_id TEXT NOT NULL REFERENCES comics(id) ON DELETE CASCADE,media_id INTEGER NOT NULL,media_title TEXT NOT NULL,first_chapter INTEGER NOT NULL DEFAULT 1,synced_progress INTEGER NOT NULL DEFAULT 0,completed_progress INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,comic_id));
CREATE TABLE remote_mounts (id TEXT PRIMARY KEY,url TEXT NOT NULL,username TEXT NOT NULL DEFAULT '',password TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1,state TEXT NOT NULL DEFAULT 'idle',message TEXT NOT NULL DEFAULT '');
CREATE TABLE storage_ledger (key TEXT PRIMARY KEY,size INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'reserved',created_at INTEGER NOT NULL);
ALTER TABLE progress ADD COLUMN anchor_paragraph INTEGER;
ALTER TABLE progress ADD COLUMN anchor_offset INTEGER;
ALTER TABLE comics ADD COLUMN hero_key TEXT;
ALTER TABLE comics ADD COLUMN mobile_hero_key TEXT;
ALTER TABLE books ADD COLUMN hero_key TEXT;
ALTER TABLE books ADD COLUMN mobile_hero_key TEXT;
CREATE TABLE compute_jobs (id TEXT PRIMARY KEY,kind TEXT NOT NULL,input_key TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued',lease_until INTEGER NOT NULL DEFAULT 0,message TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX compute_jobs_input ON compute_jobs(kind,input_key) WHERE state IN ('queued','running');
CREATE TABLE uploads (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),object_key TEXT NOT NULL,upload_id TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,mime TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'uploading',created_at INTEGER NOT NULL);
CREATE TABLE upload_parts (upload_id TEXT NOT NULL REFERENCES uploads(id) ON DELETE CASCADE,part_number INTEGER NOT NULL,etag TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(upload_id,part_number));
ALTER TABLE chapters ADD COLUMN remote_url TEXT;
ALTER TABLE chapters ADD COLUMN mount_id TEXT;
ALTER TABLE chapters ADD COLUMN source_version TEXT;
ALTER TABLE comics ADD COLUMN comic_format INTEGER NOT NULL DEFAULT 2;
ALTER TABLE chapters ADD COLUMN public_id TEXT;
ALTER TABLE chapters ADD COLUMN legacy_filename TEXT;
CREATE UNIQUE INDEX chapter_public_id ON chapters(comic_id,public_id) WHERE public_id IS NOT NULL;
ALTER TABLE comic_progress ADD COLUMN total_chapters INTEGER NOT NULL DEFAULT 0;
ALTER TABLE comic_progress ADD COLUMN total_pages INTEGER NOT NULL DEFAULT 0;
ALTER TABLE remote_mounts ADD COLUMN base_url TEXT NOT NULL DEFAULT '';
ALTER TABLE remote_mounts ADD COLUMN root TEXT NOT NULL DEFAULT '/';
ALTER TABLE remote_mounts ADD COLUMN cache_gb REAL NOT NULL DEFAULT 10;
ALTER TABLE comics ADD COLUMN banner_key TEXT;
ALTER TABLE comics ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}';
ALTER TABLE reading_time ADD COLUMN media_name TEXT NOT NULL DEFAULT '';
